p='README.md'
s=open(p,encoding='utf-8').read()
old="`bash src/list.sh [日付]` で一覧を出す。"
new="`bash src/list.sh [--room <部屋>] [日付]` で一覧を出す（`--room` で部屋を絞る）。"
assert s.count(old)==1
