[ "$code" = 2 ] && [ "$out" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value: exit $code, '$out'"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null); code=$?
[ "$code" = 2 ] && [ "$out" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date: exit $code, '$out'"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null)" ] || { echo "list bad date wrote stdout"; fail=1; }
for bad in 2026-13-01 2026-00-01 2026-01-32 2026-01-00; do
  BOOKINGS=$t bash src/list.sh "$bad" >/dev/null 2>&1; [ $? = 2 ] || { echo "list accepted $bad"; fail=1; }
done
BOOKINGS=$t bash src/list.sh 2026-01-01 >/dev/null 2>&1 || { echo "list rejected valid date"; fail=1; }
rm -f "$t"; exit $fail
EOF
python3 - <<'EOF'
p='README.md'
s=open(p,encoding='utf-8').read()
old="`bash src/list.sh [日付]` で一覧を出す。"
new="`bash src/list.sh [--room <部屋>] [日付]` で一覧を出す（`--room` で部屋を絞る）。"
assert s.count(old)==1
open(p,'w',encoding='utf-8').write(s.replace(old,new))
EOF
cat README.md; bash spec/list_room.spec.sh; echo rc=$?; bash spec/list_args.spec.sh; echo rc=$?; bash tools/check; bash tools/lint; bash src/list.sh; bash src/list.sh 2026-11-10; bash src/list.sh --room aoi 2026-11-10; bash src/list.sh --room

